import json
import copy

def solve():
    houses = 6
    categories = ["Name", "Lunch", "Height", "Favorite drink", "Pet", "Phone"]

    values = {
        "Name": ["Arnold", "Bob", "Peter", "Alice", "Carol", "Eric"],
        "Lunch": ["stew", "grilled cheese", "stir fry", "soup", "pizza", "spaghetti"],
        "Height": ["tall", "average", "super tall", "very short", "very tall", "short"],
        "Favorite drink": ["root beer", "boba tea", "coffee", "water", "tea", "milk"],
        "Pet": ["hamster", "fish", "cat", "dog", "bird", "rabbit"],
        "Phone": ["samsung galaxy s21", "xiaomi mi 11", "google pixel 6", "iphone 13", "huawei p50", "oneplus 9"],
    }

    # Initialize domains
    domains = [
        {cat: set(values[cat]) for cat in categories}
        for _ in range(houses)
    ]

    # Helper functions for propagation
    def set_value(dom, h, cat, val):
        changed = False
        if val not in dom[h][cat]:
            return False, True  # contradiction
        if len(dom[h][cat]) != 1:
            dom[h][cat] = {val}
            changed = True
        return changed, False

    def remove_value(dom, h, cat, val):
        if val in dom[h][cat]:
            dom[h][cat].remove(val)
            if len(dom[h][cat]) == 0:
                return True, True  # changed, contradiction
            return True, False
        return False, False

    # Uniqueness enforcement
    def enforce_uniqueness(dom):
        changed = False
        # Each category has unique values across houses
        for cat in categories:
            # If a house has singleton, remove from others
            singles = [(i, next(iter(dom[i][cat]))) for i in range(houses) if len(dom[i][cat]) == 1]
            for i, val in singles:
                for j in range(houses):
                    if j != i and val in dom[j][cat]:
                        ch, contra = remove_value(dom, j, cat, val)
                        if contra:
                            return True, True
                        changed = changed or ch
            # Each value must appear in at least one house; and if exactly one possible house, set it
            for val in values[cat]:
                possible = [i for i in range(houses) if val in dom[i][cat]]
                if len(possible) == 0:
                    return True, True
                if len(possible) == 1:
                    i = possible[0]
                    ch, contra = set_value(dom, i, cat, val)
                    if contra:
                        return True, True
                    changed = changed or ch
        return changed, False

    # Equivalence constraints list: (cat1,val1) <-> (cat2,val2)
    equivalences = []

    def add_equivalence(cat1, val1, cat2, val2):
        equivalences.append((cat1, val1, cat2, val2))

    def enforce_equivalences(dom):
        changed = False
        for (cat1, val1, cat2, val2) in equivalences:
            for h in range(houses):
                # If val1 impossible here, remove val2
                if val1 not in dom[h][cat1] and val2 in dom[h][cat2]:
                    ch, contra = remove_value(dom, h, cat2, val2)
                    if contra:
                        return True, True
                    changed = changed or ch
                # If val2 impossible here, remove val1
                if val2 not in dom[h][cat2] and val1 in dom[h][cat1]:
                    ch, contra = remove_value(dom, h, cat1, val1)
                    if contra:
                        return True, True
                    changed = changed or ch
                # If cat1 fixed to val1, fix cat2 to val2
                if dom[h][cat1] == {val1} and dom[h][cat2] != {val2}:
                    ch, contra = set_value(dom, h, cat2, val2)
                    if contra:
                        return True, True
                    changed = changed or ch
                # If cat2 fixed to val2, fix cat1 to val1
                if dom[h][cat2] == {val2} and dom[h][cat1] != {val1}:
                    ch, contra = set_value(dom, h, cat1, val1)
                    if contra:
                        return True, True
                    changed = changed or ch
        return changed, False

    # Direct-left constraints: (cat1,val1) is directly left of (cat2,val2)
    direct_lefts = []

    def add_direct_left(cat1, val1, cat2, val2):
        direct_lefts.append((cat1, val1, cat2, val2))

    def enforce_direct_lefts(dom):
        changed = False
        for (cat1, val1, cat2, val2) in direct_lefts:
            # Edge eliminations
            ch, contra = remove_value(dom, houses-1, cat1, val1)  # cannot be at last
            if contra:
                return True, True
            changed = changed or ch
            ch, contra = remove_value(dom, 0, cat2, val2)  # cannot be at first
            if contra:
                return True, True
            changed = changed or ch

            for i in range(houses):
                # If val1 at i, then val2 must be at i+1
                if val1 in dom[i][cat1]:
                    if i+1 >= houses or val2 not in dom[i+1][cat2]:
                        ch, contra = remove_value(dom, i, cat1, val1)
                        if contra:
                            return True, True
                        changed = changed or ch
                # If val2 at i, then val1 must be at i-1
                if val2 in dom[i][cat2]:
                    if i-1 < 0 or val1 not in dom[i-1][cat1]:
                        ch, contra = remove_value(dom, i, cat2, val2)
                        if contra:
                            return True, True
                        changed = changed or ch

                # If cat1 fixed to val1 at i, fix cat2 at i+1 to val2
                if dom[i][cat1] == {val1}:
                    if i+1 >= houses:
                        return True, True
                    ch, contra = set_value(dom, i+1, cat2, val2)
                    if contra:
                        return True, True
                    changed = changed or ch

                # If cat2 fixed to val2 at i, fix cat1 at i-1 to val1
                if dom[i][cat2] == {val2}:
                    if i-1 < 0:
                        return True, True
                    ch, contra = set_value(dom, i-1, cat1, val1)
                    if contra:
                        return True, True
                    changed = changed or ch

        return changed, False

    # Left-of (somewhere to the left, not necessarily adjacent): (cat1,val1) left of (cat2,val2)
    left_ofs = []

    def add_left_of(cat1, val1, cat2, val2):
        left_ofs.append((cat1, val1, cat2, val2))

    def enforce_left_ofs(dom):
        changed = False
        for (cat1, val1, cat2, val2) in left_ofs:
            for i in range(houses):
                # If val1 at i, then there must be some j > i with val2 possible
                if val1 in dom[i][cat1]:
                    possible_right = any(val2 in dom[j][cat2] for j in range(i+1, houses))
                    if not possible_right:
                        ch, contra = remove_value(dom, i, cat1, val1)
                        if contra:
                            return True, True
                        changed = changed or ch
                # If val2 at i, then there must be some j < i with val1 possible
                if val2 in dom[i][cat2]:
                    possible_left = any(val1 in dom[j][cat1] for j in range(0, i))
                    if not possible_left:
                        ch, contra = remove_value(dom, i, cat2, val2)
                        if contra:
                            return True, True
                        changed = changed or ch

                # If cat1 fixed at i, remove val2 from j <= i
                if dom[i][cat1] == {val1}:
                    for j in range(0, i+1):
                        if val2 in dom[j][cat2]:
                            ch, contra = remove_value(dom, j, cat2, val2)
                            if contra:
                                return True, True
                            changed = changed or ch
                # If cat2 fixed at i, remove val1 from j >= i
                if dom[i][cat2] == {val2}:
                    for j in range(i, houses):
                        if val1 in dom[j][cat1]:
                            ch, contra = remove_value(dom, j, cat1, val1)
                            if contra:
                                return True, True
                            changed = changed or ch
        return changed, False

    def propagate(dom):
        while True:
            changed = False

            # Uniqueness
            ch, contra = enforce_uniqueness(dom)
            if contra:
                return True
            changed = changed or ch

            # Equivalences
            ch, contra = enforce_equivalences(dom)
            if contra:
                return True
            changed = changed or ch

            # Direct-left
            ch, contra = enforce_direct_lefts(dom)
            if contra:
                return True
            changed = changed or ch

            # Left-of
            ch, contra = enforce_left_ofs(dom)
            if contra:
                return True
            changed = changed or ch

            # If no change, break
            if not changed:
                break
        return False

    # Add all constraints

    # 1. iPhone 13 in third house.
    domains[2]["Phone"] = {"iphone 13"}
    # 3. Soup in second house.
    domains[1]["Lunch"] = {"soup"}
    # 2. Bob is tall.
    add_equivalence("Name", "Bob", "Height", "tall")
    # 7. Grilled cheese is tall.
    add_equivalence("Lunch", "grilled cheese", "Height", "tall")
    # 5. Huawei P50 directly left of grilled cheese.
    add_direct_left("Phone", "huawei p50", "Lunch", "grilled cheese")
    # 8. Xiaomi Mi 11 is the coffee drinker.
    add_equivalence("Phone", "xiaomi mi 11", "Favorite drink", "coffee")
    # 4. Root beer directly left of Xiaomi Mi 11.
    add_direct_left("Favorite drink", "root beer", "Phone", "xiaomi mi 11")
    # 6. Stir fry is the person who likes milk.
    add_equivalence("Lunch", "stir fry", "Favorite drink", "milk")
    # 26. Dog is the person who likes milk.
    add_equivalence("Pet", "dog", "Favorite drink", "milk")
    # 9. OnePlus 9 is Arnold.
    add_equivalence("Phone", "oneplus 9", "Name", "Arnold")
    # 10. Rabbit not in fifth house.
    domains[4]["Pet"].discard("rabbit")
    # 20. Hamster not in fifth house.
    domains[4]["Pet"].discard("hamster")
    # 11. Hamster to the right of Google Pixel 6.
    add_left_of("Phone", "google pixel 6", "Pet", "hamster")
    # 12. Super tall is fish.
    add_equivalence("Height", "super tall", "Pet", "fish")
    # 13. Fish is Alice.
    add_equivalence("Pet", "fish", "Name", "Alice")
    # 25. Fish directly left of Eric.
    add_direct_left("Pet", "fish", "Name", "Eric")
    # 22. Super tall somewhere to the left of Peter.
    add_left_of("Height", "super tall", "Name", "Peter")
    # 14. Tea directly left of pizza.
    add_direct_left("Favorite drink", "tea", "Lunch", "pizza")
    # 16. Pizza is short.
    add_equivalence("Lunch", "pizza", "Height", "short")
    # 15. Samsung Galaxy S21 is Carol.
    add_equivalence("Phone", "samsung galaxy s21", "Name", "Carol")
    # 17. Arnold is very tall.
    add_equivalence("Name", "Arnold", "Height", "very tall")
    # 21. Very tall not in the second house.
    domains[1]["Height"].discard("very tall")
    # 18. Spaghetti eater uses Google Pixel 6. (interpreting ambiguous clue)
    add_equivalence("Lunch", "spaghetti", "Phone", "google pixel 6")
    # 23. Very short is spaghetti eater. (interpreting ambiguous clue)
    add_equivalence("Height", "very short", "Lunch", "spaghetti")
    # 24. Bird left of spaghetti eater.
    add_left_of("Pet", "bird", "Lunch", "spaghetti")
    # 19. Boba tea to the right of soup.
    add_left_of("Lunch", "soup", "Favorite drink", "boba tea")
    # 1 and 3 already set
    # 6 & 26 already linked to milk -> stir fry and dog

    # Additional implicit: "The person who uses an iPhone 13 is in the third house" means other houses cannot have 'iphone 13'
    for i in range(houses):
        if i != 2:
            domains[i]["Phone"].discard("iphone 13")

    # Propagate initial constraints
    if propagate(domains):
        raise ValueError("Contradiction during initial propagation")

    # Backtracking search
    def is_complete(dom):
        return all(all(len(dom[i][cat]) == 1 for cat in categories) for i in range(houses))

    def select_unassigned(dom):
        # Choose the house,category with smallest domain > 1
        best = None
        best_size = 999
        for i in range(houses):
            for cat in categories:
                size = len(dom[i][cat])
                if size > 1 and size < best_size:
                    best = (i, cat)
                    best_size = size
        return best

    def deepcopy_domains(dom):
        return [ {cat: set(dom[i][cat]) for cat in categories} for i in range(houses) ]

    def search(dom):
        if is_complete(dom):
            return dom
        sel = select_unassigned(dom)
        if not sel:
            return None
        i, cat = sel
        for val in list(dom[i][cat]):
            new_dom = deepcopy_domains(dom)
            ch, contra = set_value(new_dom, i, cat, val)
            if contra:
                continue
            if propagate(new_dom):
                continue
            result = search(new_dom)
            if result is not None:
                return result
        return None

    solution_domains = search(domains)
    if solution_domains is None:
        raise ValueError("No solution found")

    # Build solution rows
    header = ["House"] + categories
    rows = []
    for i in range(houses):
        row = [str(i+1)]
        for cat in categories:
            val = next(iter(solution_domains[i][cat]))
            row.append(val)
        rows.append(row)

    return {
        "solution": {
            "header": header,
            "rows": rows
        }
    }

if __name__ == "__main__":
    result = solve()
    print(json.dumps(result, indent=2))
